public class Main {
    public static void main(String[] args) {
        int x = 10; // Stack
        String name = "Java"; // Stack reference -> String Pool (Heap)

        Person p = new Person("Jammy"); // Stack reference -> Heap Object

        p.sayHello();
        // After this method ends, x, name, p are popped from Stack.
        // The Person object in Heap becomes unreachable (Garbage).
    }
}

class Person {
    String name; // Heap (instance variable)

    public Person(String name) {
        this.name = name;
    }

    public void sayHello() {
        System.out.println("Hello, " + name);
    }
}
